const pool = require("../config/db");

const getProducts = async (req, res) => {
  try {

    const result = await pool.query(`
      SELECT
        p.id,
        p.title,
        p.description,
        p.price,
        p.stock,
        p.image_url,
        c.name AS category
      FROM products p
      JOIN categories c
        ON p.category_id = c.id
      ORDER BY p.id;
    `);

    res.json(result.rows);

  } catch (error) {

    console.error("GET PRODUCTS ERROR:", error);

    res.status(500).json({
      success: false,
      message: "Failed to fetch products"
    });

  }
};

module.exports = {
  getProducts
};
